pub fn credential_on_outcome(sent: u64, current: u64, outcome: u8) -> bool {
    let outcome = match outcome {
        0 => Outcome::Accepted,
        1 => Outcome::Refused,
        _ => Outcome::Failed,
    };
    credential::on_outcome(Generation::from(sent), Generation::from(current), outcome)
}

